import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`concrete-estimate`,heroTitle:`Generate concrete estimates in minutes`,heroSubtitle:`Perplexity Computer analyzes your uploaded plans, sizes concrete volume, labor, and placement work, and drafts a detailed concrete estimate automatically.`,hasInputUrl:!1,hasInputFile:!0,inputFileCta:`Upload your concrete plans`,inputFileAccept:`.pdf,.doc,.docx,.csv,.xlsx,.xls,.png,.jpg,.jpeg`,inputFilePrefill:`I've uploaded concrete plans, takeoffs, or site notes. Build a complete concrete estimate. (1) Extract pour areas, slab depths, reinforcement, formwork, finish requirements, joints, and site access from the uploaded files. (2) Estimate concrete volume, reinforcement, formwork, pumping, labor, and finishing work. (3) Build pricing options with assumptions, alternates, mobilization, and margin. (4) Highlight exclusions, field-verification items, and schedule risks that should be confirmed before sending. (5) Deliver a detailed concrete estimate with line-item pricing, scope summary, and next steps that is ready for the customer.`,heroOverlaySteps:[`Extracting pour areas, slab depths, reinforcement, and site access from your files`,`Sizing concrete volume, formwork, labor, pumping, and finishing work`,`Building pricing options with assumptions, alternates, and margin`,`Customer-ready concrete estimate with scope summary, ready to send`],generatingSteps:[`Reading the uploaded plans, takeoffs, and site notes`,`Designing an agent to organize quantity takeoffs and crew assumptions`,`Configuring estimate logic for alternates, mobilization, and margin`,`Preparing a detailed concrete estimate with line items and next steps`],featureSectionTitle:`From plans to pour-ready estimate`,featureCardTitles:[`Connects to your estimating workflow`,`Estimates built for field reality`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Docs, sheets, takeoffs, and internal review workflows stay connected so estimates and revisions move faster.`,`Takeoff quantities. Crew assumptions. Placement details. Computer gives your team a concrete estimate draft that is ready for customer review.`],capabilitySectionTitle:`Your estimator, on autopilot`,capabilitySectionSubtitle:`Upload the plans, get back a concrete estimate built around the real pour scope.`,capabilityCards:[{title:`Plan Analysis`,description:`Computer can extract pour areas, slab depths, reinforcement, joints, finish requirements, and site constraints from concrete plans and job notes.`},{title:`Materials & Labor Planning`,description:`Computer can size concrete volume, formwork, reinforcement, pumping, and labor hours so the estimate reflects the real scope of work.`},{title:`Pricing Options`,description:`Computer can turn the scope into pricing with assumptions, alternates, mobilization, and margin so your estimate is easier to review and send.`},{title:`Connect Your Tools`,description:`Computer can organize estimate drafts across docs, sheets, and internal workflows so review and handoff are easy for your team.`},{title:`Knows Your Standards`,description:`Computer can remember your preferred production rates, markup rules, and estimate structure across sessions so every quote stays consistent.`},{title:`Revision Support`,description:`Computer can update the estimate when quantities, finish requirements, or site conditions change after the first draft.`}]});export{t as default};
